<?= $this->extend('layouts/asistenciaLayout') ?>
<?= $this->section('title') ?>UPSS por establecimiento<?= $this->endSection() ?>
<?= $this->section('content') ?>
<div class="card bg-white p-4" id="eup-app" data-api="<?= site_url('asistencia/gestordb/api/establecimiento-upss') ?>" data-catalogos="<?= site_url('asistencia/gestordb/api/establecimiento-upss/catalogos') ?>">
    <div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h4 class="mb-1 fw-bold">UPSS por establecimiento</h4><p class="text-muted small mb-0">Administre qué unidades productoras están habilitadas en cada establecimiento.</p></div><div class="d-flex flex-wrap gap-2 align-items-end"><div><label class="form-label small mb-1" for="filtroEst">Establecimiento</label><select id="filtroEst" class="form-select form-select-sm" style="min-width:260px"><option value="">Todos los establecimientos</option></select></div><div><label class="form-label small mb-1" for="filtroEstado">Estado</label><select id="filtroEstado" class="form-select form-select-sm"><option value="">Todos</option><option value="1">Activos</option><option value="0">Inactivos</option></select></div><button id="btnNuevaEup" class="btn btn-primary btn-sm"><i class="ti ti-plus"></i> Nueva relación</button></div></div>
    <div class="table-responsive"><table id="tablaEup" class="table table-hover align-middle w-100"><thead><tr><th>ID</th><th>Establecimiento</th><th>Red</th><th>Código UPSS</th><th>UPSS</th><th>Agrupación</th><th>Observación</th><th>Estado</th><th>Actualizado</th><th class="text-end">Acciones</th></tr></thead><tbody></tbody></table></div>
</div>
<div class="modal fade" id="modalEup" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 id="tituloEup" class="modal-title">Vincular UPSS</h5><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Cerrar"></button></div><form id="formEup"><div class="modal-body"><input type="hidden" id="eup_ide" value=""><input type="hidden" name="<?= csrf_token() ?>" value="<?= csrf_hash() ?>"><div class="mb-3"><label class="form-label" for="eup_est_ide">Establecimiento</label><select id="eup_est_ide" name="eup_est_ide" class="form-select" required><option value="">Seleccione...</option></select></div><div class="mb-3"><label class="form-label" for="eup_ups_ide">UPSS</label><select id="eup_ups_ide" name="eup_ups_ide" class="form-select" required><option value="">Seleccione...</option></select></div><div class="mb-3"><label class="form-label" for="eup_observacion">Observación</label><textarea id="eup_observacion" name="eup_observacion" class="form-control" rows="3" maxlength="60000"></textarea></div><div class="form-check form-switch"><input id="eup_estado" name="eup_estado" class="form-check-input" type="checkbox" value="1" checked><label for="eup_estado" class="form-check-label">Relación activa</label></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancelar</button><button id="btnGuardarEup" class="btn btn-primary" type="submit">Guardar</button></div></form></div></div></div>
<?= $this->endSection() ?>
<?= $this->section('pageScripts') ?>
<script>
(()=>{
 const root=document.getElementById('eup-app');if(!root)return;const api=root.dataset.api,csrfName='<?= csrf_token() ?>';let csrfHash='<?= csrf_hash() ?>',catalogos={},tabla,modal;
 const load=title=>Swal.fire({title,text:'Espere un momento…',allowOutsideClick:false,allowEscapeKey:false,didOpen:()=>Swal.showLoading()});const close=()=>Swal.close();
 async function request(url,method='GET',data=null){const options={method,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}};if(data){data[csrfName]=csrfHash;options.headers['Content-Type']='application/x-www-form-urlencoded;charset=UTF-8';options.body=new URLSearchParams(data);}const res=await fetch(url,options);const json=await res.json();if(json.csrfHash)csrfHash=json.csrfHash;if(!res.ok||json.status==='error'){const err=new Error(json.message||Object.values(json.messages||{}).join('\n')||'No se pudo completar la solicitud.');throw err;}return json;}
 function html(v){return $('<div>').text(v??'').html();}
 function llenar(select,items,idField,label){select.innerHTML='<option value="">Seleccione...</option>';for(const item of items)select.append(new Option(label(item),item[idField]));}
 function llenarUpss(soloActivas){const lista=soloActivas?catalogos.upss.filter(u=>Number(u.ups_estado)===1):catalogos.upss;llenar(document.getElementById('eup_ups_ide'),lista,'ups_ide',u=>(u.ups_codigo?u.ups_codigo+' · ':'')+u.ups_nombre+(Number(u.ups_estado)===1?'':' (inactiva)'));}
 async function inicio(){load('Cargando establecimientos y UPSS');try{catalogos=await request(root.dataset.catalogos);llenar(document.getElementById('filtroEst'),catalogos.establecimientos,'est_ide',e=>(e.est_ipress?e.est_ipress+' · ':'')+e.est_nombre);llenar(document.getElementById('eup_est_ide'),catalogos.establecimientos,'est_ide',e=>(e.est_ipress?e.est_ipress+' · ':'')+e.est_nombre);llenarUpss(false);close();crearTabla();}catch(e){close();Swal.fire({icon:'error',title:'No se pudieron cargar los catálogos',text:e.message});}}
 function crearTabla(){tabla=$('#tablaEup').DataTable({ajax:{url:api,data:d=>{d.establecimiento=$('#filtroEst').val();d.estado=$('#filtroEstado').val();},dataSrc:'data'},columns:[{data:'eup_ide'},{data:null,render:(v,t,r)=>`${r.est_ipress?`<span class="text-muted">${html(r.est_ipress)}</span> · `:''}${html(r.est_nombre)}`},{data:'red_nombre',render:v=>html(v||'-')},{data:'ups_codigo',render:v=>html(v||'-')},{data:'ups_nombre',render:html},{data:'ups_agrupacion',render:v=>html(v||'-')},{data:'eup_observacion',render:v=>html(v||'-')},{data:'eup_estado',render:v=>Number(v)===1?'<span class="badge bg-success-subtle text-success">Activo</span>':'<span class="badge bg-secondary-subtle text-secondary">Inactivo</span>'},{data:'updated_at',render:v=>html(v?v.split(' ')[0]:'-')},{data:null,orderable:false,searchable:false,className:'text-end',render:(v,t,r)=>`<button type="button" class="btn btn-outline-primary btn-sm js-edit" data-id="${r.eup_ide}" title="Editar" aria-label="Editar"><iconify-icon icon="lucide:edit-2"></iconify-icon></button> <button type="button" class="btn btn-outline-danger btn-sm js-delete" data-id="${r.eup_ide}" title="Eliminar" aria-label="Eliminar"><iconify-icon icon="lucide:trash-2"></iconify-icon></button>`}],order:[[1,'asc'],[4,'asc']],pageLength:25,language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_ registros',zeroRecords:'No se encontraron relaciones',emptyTable:'No hay UPSS asignadas',info:'Mostrando _START_ a _END_ de _TOTAL_',paginate:{first:'Primero',last:'Último',next:'Siguiente',previous:'Anterior'}}});$('#tablaEup').on('click','.js-edit',editar).on('click','.js-delete',eliminar);}
 function abrirNuevo(){document.getElementById('formEup').reset();$('#eup_ide').val('');llenarUpss(true);$('#eup_estado').prop('checked',true);$('#eup_est_ide,#eup_ups_ide').prop('disabled',false);$('#tituloEup').text('Vincular UPSS al establecimiento');modal.show();}
 function editar(){const r=tabla.row($(this).closest('tr')).data();$('#formEup')[0].reset();llenarUpss(false);$('#eup_ide').val(r.eup_ide);$('#eup_est_ide').val(String(r.eup_est_ide));$('#eup_ups_ide').val(String(r.eup_ups_ide));$('#eup_observacion').val(r.eup_observacion||'');$('#eup_estado').prop('checked',Number(r.eup_estado)===1);$('#tituloEup').text('Editar relación establecimiento-UPSS');$('#eup_est_ide,#eup_ups_ide').prop('disabled',false);modal.show();}
 async function guardar(ev){ev.preventDefault();const id=$('#eup_ide').val(),method=id?'PUT':'POST',url=id?`${api}/${id}`:api;const data={eup_est_ide:$('#eup_est_ide').val(),eup_ups_ide:$('#eup_ups_ide').val(),eup_observacion:$('#eup_observacion').val(),eup_estado:$('#eup_estado').is(':checked')?'1':'0'};$('#btnGuardarEup').prop('disabled',true);load(id?'Actualizando relación':'Vinculando UPSS');try{const result=await request(url,method,data);close();modal.hide();Swal.fire({icon:'success',title:'Guardado',text:result.message});tabla.ajax.reload(null,false);}catch(e){close();Swal.fire({icon:'error',title:'No se pudo guardar',text:e.message});}finally{$('#btnGuardarEup').prop('disabled',false);$('#formEup input[name="'+csrfName+'"]').val(csrfHash);}}
 async function eliminar(){const id=$(this).data('id'),r=await Swal.fire({title:'¿Archivar esta relación?',text:'Se ocultará de las opciones activas, conservando el historial de programación.',icon:'warning',showCancelButton:true,confirmButtonText:'Archivar',cancelButtonText:'Cancelar',confirmButtonColor:'#d33'});if(!r.isConfirmed)return;load('Archivando relación');try{const result=await request(`${api}/${id}`,'DELETE',{});close();Swal.fire({icon:'success',title:'Archivada',text:result.message});tabla.ajax.reload(null,false);}catch(e){close();Swal.fire({icon:'error',title:'No se pudo archivar',text:e.message});}}
 document.addEventListener('DOMContentLoaded',()=>{modal=new bootstrap.Modal(document.getElementById('modalEup'));$('#formEup').on('submit',guardar);$('#btnNuevaEup').on('click',abrirNuevo);$('#filtroEst,#filtroEstado').on('change',()=>tabla?.ajax.reload());inicio();});
})();
</script>
<?= $this->endSection() ?>
